import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import { createClient } from '@supabase/supabase-js';

// Accept only credentials generated by the ephemeral local stack. Never use .env.
const file = process.argv[2];
if (!file) throw new Error('Pass the isolated Supabase status env file');
const env = Object.fromEntries((await readFile(file, 'utf8')).split(/\r?\n/).filter(line => /^[A-Z_]+=/.test(line)).map(line => {
  const split = line.indexOf('=');
  const key = line.slice(0, split);
  const raw = line.slice(split + 1);
  return [key, raw.startsWith('"') ? JSON.parse(raw) : raw];
}));
const api = env.API_URL;
if (!api || !['localhost', '127.0.0.1', '[::1]'].includes(new URL(api).hostname)) throw new Error('Refusing non-local Supabase');
if (!env.ANON_KEY || !env.SERVICE_ROLE_KEY) throw new Error('Missing isolated stack keys');
const options = { auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false } };
const admin = createClient(api, env.SERVICE_ROLE_KEY, options);
const client = () => createClient(api, env.ANON_KEY, options);
const ok = (result, label) => {
  if (result.error) throw new Error(label + ': ' + result.error.message);
  return result.data;
};
let count = 0;
async function test(name, fn) {
  await fn();
  count++;
  console.log('PASS ' + name);
}
async function account(role) {
  const email = randomUUID() + '@example.invalid';
  const password = 'Local-' + randomUUID() + '-42';
  const { user } = ok(await admin.auth.admin.createUser({email, password, email_confirm: true}), 'create local user');
  ok(await admin.from('user_roles').upsert({user_id:user.id,role},{onConflict:'user_id,role'}), 'assign local role');
  const sdk = client();
  ok(await sdk.auth.signInWithPassword({email,password}), 'local sign-in');
  return {id:user.id,email,password,sdk};
}
const a = await account('client');
const b = await account('client');
const manager = await account('manager');
const owner = await account('admin');
const support = await account('support');
const calculation = user_id => ({user_id,volume_nf:10000,peso_liquido:8350,massa_especifica_20_nf:840,temperatura_amostra:25,densidade_amostra:0.835,temperatura_ct:25});

await test('real Auth session and own calculation are usable', async () => {
  assert.equal(ok(await a.sdk.rpc('is_account_ready'),'eligibility'),true);
  ok(await a.sdk.from('calculations').insert(calculation(a.id)),'own calculation');
});
await test('client A cannot read or write client B calculations', async () => {
  ok(await b.sdk.from('calculations').insert(calculation(b.id)),'B calculation');
  const visible = ok(await a.sdk.from('calculations').select('user_id'),'read own history');
  assert.deepEqual(visible.map(row=>row.user_id),[a.id]);
  assert.ok((await a.sdk.from('calculations').insert(calculation(b.id))).error);
});
await test('staff retains monitoring but manager/support cannot update client or staff profiles directly', async () => {
  for (const staff of [manager,support]) {
    assert.equal(ok(await staff.sdk.from('calculations').select('id'),'staff monitoring').length,2);
    for (const target of [a,owner]) {
      const changed = ok(await staff.sdk.from('profiles').update({is_active:false}).eq('user_id',target.id).select('user_id'),'restricted target');
      assert.equal(changed.length,0);
    }
  }
  assert.equal(ok(await owner.sdk.from('profiles').update({full_name:'Approved client'}).eq('user_id',a.id).select('user_id'),'owner edit').length,1);
});
await test('active JWT loses operational access immediately after profile deactivation', async () => {
  ok(await admin.from('profiles').update({is_active:false}).eq('user_id',a.id),'deactivate locally');
  assert.equal(ok(await a.sdk.rpc('is_account_ready'),'disabled eligibility'),false);
  assert.equal(ok(await a.sdk.from('calculations').select('id'),'disabled history').length,0);
  assert.ok((await a.sdk.from('calculations').insert(calculation(a.id))).error);
  assert.ok((await a.sdk.rpc('clear_must_change_password')).error);
});
await test('mandatory password flag cannot be cleared by RPC or metadata updates', async () => {
  ok(await admin.from('profiles').update({must_change_password:true}).eq('user_id',b.id),'require password');
  assert.equal(ok(await b.sdk.rpc('is_account_ready'),'pending eligibility'),false);
  assert.ok((await b.sdk.rpc('clear_must_change_password')).error);
  ok(await b.sdk.auth.updateUser({data:{full_name:'Metadata is not a password'}}),'metadata update');
  assert.ok((await b.sdk.rpc('clear_must_change_password')).error);
});
await test('real GoTrue password update produces private proof and releases the account', async () => {
  ok(await b.sdk.auth.updateUser({password:'Changed-'+randomUUID()+'-42'}),'real password change');
  ok(await b.sdk.rpc('clear_must_change_password'),'confirmed password flag');
  assert.equal(ok(await b.sdk.rpc('is_account_ready'),'confirmed eligibility'),true);
});
await test('invitation can establish a session and define the first password', async () => {
  const email = randomUUID()+'@example.invalid';
  const invited = ok(await admin.auth.admin.inviteUserByEmail(email),'local SMTP invite');
  ok(await admin.from('user_roles').upsert({user_id:invited.user.id,role:'client'},{onConflict:'user_id,role'}),'invite role');
  ok(await admin.from('profiles').update({must_change_password:true}).eq('user_id',invited.user.id),'invite flag');
  const link = ok(await admin.auth.admin.generateLink({type:'invite',email}),'local invite link');
  const invitedClient = client();
  ok(await invitedClient.auth.verifyOtp({type:'invite',token_hash:link.properties.hashed_token}),'verify invitation');
  assert.ok((await invitedClient.rpc('clear_must_change_password')).error);
  ok(await invitedClient.auth.updateUser({password:'Invited-'+randomUUID()+'-42'}),'define invited password');
  ok(await invitedClient.rpc('clear_must_change_password'),'release invited user');
  assert.equal(ok(await invitedClient.rpc('is_account_ready'),'invite eligibility'),true);
});
await test('recovery can establish a session and clear a newly required password change', async () => {
  ok(await admin.from('profiles').update({must_change_password:true}).eq('user_id',b.id),'require recovery change');
  ok(await b.sdk.auth.resetPasswordForEmail(b.email),'local SMTP recovery');
  const link = ok(await admin.auth.admin.generateLink({type:'recovery',email:b.email}),'local recovery link');
  const recovered = client();
  ok(await recovered.auth.verifyOtp({type:'recovery',token_hash:link.properties.hashed_token}),'verify recovery');
  assert.ok((await recovered.rpc('clear_must_change_password')).error);
  ok(await recovered.auth.updateUser({password:'Recovered-'+randomUUID()+'-42'}),'recovery password update');
  ok(await recovered.rpc('clear_must_change_password'),'release recovered user');
  assert.equal(ok(await recovered.rpc('is_account_ready'),'recovery eligibility'),true);
});
console.log('Passed '+count+' isolated Supabase Auth/API checks');
